import { buttonVariants } from "@/components/ui/button";
import {
	Pagination,
	PaginationContent,
	PaginationEllipsis,
	PaginationItem,
	PaginationLink,
} from "@/components/ui/pagination";
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react";

import { cn } from "../utilities/cn";
import { usePagination } from "../utilities/usePagination";

type PaginationProps = {
	currentPage: number;
	totalPages: number;
	paginationItemsToDisplay?: number;
};

export default function Component({
	currentPage,
	totalPages,
	paginationItemsToDisplay = 5,
}: PaginationProps) {
	const { pages, showLeftEllipsis, showRightEllipsis } = usePagination({
		currentPage,
		totalPages,
		paginationItemsToDisplay,
	});

	return (
		<Pagination>
			<PaginationContent className="inline-flex gap-0 -space-x-px rounded-md shadow-xs rtl:space-x-reverse">
				{/* Previous page button */}
				<PaginationItem className="[&:first-child>a]:rounded-s-md [&:last-child>a]:rounded-e-md">
					<PaginationLink
						className={cn(
							buttonVariants({
								variant: "outline",
							}),
							"rounded-none shadow-none focus-visible:z-10 aria-disabled:pointer-events-none [&[aria-disabled]>svg]:opacity-50"
						)}
						href={
							currentPage === 1 ? undefined : `#/page/${currentPage - 1}`
						}
						aria-label="Go to previous page"
						aria-disabled={currentPage === 1 ? true : undefined}
						role={currentPage === 1 ? "link" : undefined}
					>
						<ChevronLeftIcon size={16} aria-hidden="true" />
					</PaginationLink>
				</PaginationItem>

				{/* Left ellipsis (...) */}
				{showLeftEllipsis && (
					<PaginationItem className="[&:first-child>a]:rounded-s-md [&:last-child>a]:rounded-e-md">
						<PaginationEllipsis />
					</PaginationItem>
				)}

				{/* Page number links */}
				{pages.map((page) => (
					<PaginationItem key={page}>
						<PaginationLink
							className={cn(
								buttonVariants({
									variant: "outline",
								}),
								"rounded-none shadow-none focus-visible:z-10",
								page === currentPage && "bg-accent"
							)}
							href={`#/page/${page}`}
							isActive={page === currentPage}
						>
							{page}
						</PaginationLink>
					</PaginationItem>
				))}

				{/* Right ellipsis (...) */}
				{showRightEllipsis && (
					<PaginationItem className="[&:first-child>a]:rounded-s-md [&:last-child>a]:rounded-e-md">
						<PaginationEllipsis
							className={cn(
								buttonVariants({
									variant: "outline",
								}),
								"pointer-events-none rounded-none shadow-none"
							)}
						/>
					</PaginationItem>
				)}

				{/* Next page button */}
				<PaginationItem className="[&:first-child>a]:rounded-s-md [&:last-child>a]:rounded-e-md">
					<PaginationLink
						className={cn(
							buttonVariants({
								variant: "outline",
							}),
							"rounded-none shadow-none focus-visible:z-10 aria-disabled:pointer-events-none [&[aria-disabled]>svg]:opacity-50"
						)}
						href={
							currentPage === totalPages
								? undefined
								: `#/page/${currentPage + 1}`
						}
						aria-label="Go to next page"
						aria-disabled={currentPage === totalPages ? true : undefined}
						role={currentPage === totalPages ? "link" : undefined}
					>
						<ChevronRightIcon size={16} aria-hidden="true" />
					</PaginationLink>
				</PaginationItem>
			</PaginationContent>
		</Pagination>
	);
}

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

type UsePaginationProps = {
    currentPage: number
    totalPages: number
    paginationItemsToDisplay: number
}

type UsePaginationReturn = {
    pages: number[]
    showLeftEllipsis: boolean
    showRightEllipsis: boolean
}

export function usePagination({
    currentPage,
    totalPages,
    paginationItemsToDisplay,
}: UsePaginationProps): UsePaginationReturn {
    const showLeftEllipsis = currentPage - 1 > paginationItemsToDisplay / 2
    const showRightEllipsis =
        totalPages - currentPage + 1 > paginationItemsToDisplay / 2

    function calculatePaginationRange(): number[] {
        if (totalPages <= paginationItemsToDisplay) {
            return Array.from({ length: totalPages }, (_, i) => i + 1)
        }

        const halfDisplay = Math.floor(paginationItemsToDisplay / 2)
        const initialRange = {
            start: currentPage - halfDisplay,
            end: currentPage + halfDisplay,
        }

        const adjustedRange = {
            start: Math.max(1, initialRange.start),
            end: Math.min(totalPages, initialRange.end),
        }

        if (adjustedRange.start === 1) {
            adjustedRange.end = paginationItemsToDisplay
        }
        if (adjustedRange.end === totalPages) {
            adjustedRange.start = totalPages - paginationItemsToDisplay + 1
        }

        if (showLeftEllipsis) adjustedRange.start++
        if (showRightEllipsis) adjustedRange.end--

        return Array.from(
            { length: adjustedRange.end - adjustedRange.start + 1 },
            (_, i) => adjustedRange.start + i
        )
    }

    const pages = calculatePaginationRange()

    return {
        pages,
        showLeftEllipsis,
        showRightEllipsis,
    }
}
